#!/usr/bin/env python3
"""Build the self-contained review report from retained measurements, without resampling."""
import json, pathlib, io, html, collections
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import numpy as np
ROOT=pathlib.Path(__file__).resolve().parent.parent
D=ROOT/'docs/combined-verification-2026-10-21'
read=lambda n:json.loads((D/n).read_text())
b=read('realtime-cycle.json');q=read('qualification.json');ranges=read('range-configs.json');cat=read('source-catalog.json');defaults=read('default-config.json');manifest=read('source-manifest-v4.json')
assert b['sourceSha256']==q['sourceSha256']
assert len(b['series']['cycleMs'])==b['cycles']['n']==60
assert len(q['configs'])==b['historicalCohort']['qualifiedConfigs']
for f in manifest['files']:
 if f['path'].startswith('src/core/'):
  assert b['sourceManifest'][f['path']]==f['sha256'],f['path']
rows=[dict(id=c['id'],kind=c['kind'],range=c['range'],**v) for c in q['configs'] for v in c['directions'] if v['ok']]
assert len(rows)>0 and all(x['lastN']==x['lastNRequested']==15 for x in rows)
ci=read('ci-verification.json') if (D/'ci-verification.json').exists() else {'status':'pending','partitions':[]}
assert ci.get('sourceSha256')==manifest['sourceSha256'], 'CI source differs from this report'
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False,'axes.labelcolor':'#42536a','text.color':'#182b45','xtick.color':'#42536a','ytick.color':'#42536a','svg.fonttype':'none'})
charts=[]
def chart(title,draw,note):
 fig,ax=plt.subplots(figsize=(7.1,3.3),layout='constrained');draw(ax);ax.grid(axis='y',alpha=.16);ax.set_axisbelow(True)
 s=io.StringIO();fig.savefig(s,format='svg',metadata={'Date':None});plt.close(fig)
 svg=s.getvalue();svg=svg[svg.index('<svg'):]
 charts.append('<article class="chart"><h3>'+title+'</h3>'+svg+'<p>'+note+'</p></article>')
chart('01 / Foreground progress cycle',lambda a:(a.plot(range(1,61),b['series']['cycleMs'],color='#087f8c',lw=2),a.axhline(500,color='#cf5b42',ls='--'),a.set(xlabel='Completed cycle',ylabel='Milliseconds',ylim=(0,550))), 'All 60 measured cycles. The dashed line is the 500 ms budget; cold discovery and network latency are outside this measurement.')
chart('02 / Live ticker',lambda a:(a.plot(range(1,61),b['series']['ticks'],color='#5869b4',lw=2),a.set(xlabel='Completed cycle',ylabel='Milliseconds',ylim=(0,None))), 'All 60 tick measurements; owned worker computation runs separately from the ticker.')
keys=list(q['byRange']);passed=[q['byRange'][k]['passed'] for k in keys];failed=[q['byRange'][k]['built']-q['byRange'][k]['passed'] for k in keys]
chart('03 / Qualification by range',lambda a:(a.bar(keys,passed,label='Admitted configs',color='#087f8c'),a.bar(keys,failed,bottom=passed,label='Rejected configs',color='#d6deea'),a.set(ylabel='Config identities'),a.legend(frameon=False)), f'{q["passedConfigs"]} / {q["candidatesBuilt"]:,} built configs. These identities come from the fixed earlier post-Base cohort, rather than the entire strategy universe.')
pfs=[x['lastNPf'] for x in rows if not x['noLoss']];no_loss=sum(x['noLoss'] for x in rows)
chart('04 / Admitted own Last-15 PF',lambda a:(a.hist(pfs,bins=np.geomspace(min(pfs),max(pfs),28),color='#087f8c'),a.set_xscale('log'),a.set(xlabel='Own return PF, logarithmic scale',ylabel='Admitted directions')),f'{len(pfs)} finite loss-bearing windows; {no_loss} no-loss windows are separate. A no-loss score of 4 is a ranking convention, not an observed PF ratio.')
r=ranges['rows'];x=np.arange(len(r));n=np.array([z['normal'] for z in r]);t=np.array([z['trailing'] for z in r]);o=np.array([z['trailingOnly'] for z in r])
chart('05 / Default protection cells at 15m',lambda a:(a.bar(x,n,label='TP + SL',color='#087f8c'),a.bar(x,t,bottom=n,label='TP + trailing',color='#5869b4'),a.bar(x,o,bottom=n+t,label='Trailing only',color='#dfac58'),a.set_xticks(x,[z['tag'] for z in r]),a.set(ylabel='Static protect cells'),a.legend(frameon=False,fontsize=8)), '3,898 static cells. Wide has no default explicit TP; Minimal Plus fits dynamically. The identity audit adds disclosed Wide and Minimal Plus fixtures.')
chart('06 / Registered indication families',lambda a:(a.barh(list(cat['byKind']),list(cat['byKind'].values()),color=['#087f8c' if k=='inverse' else '#5869b4' for k in cat['byKind']]),a.invert_yaxis(),a.tick_params(axis='y',labelsize=8),a.set(xlabel='Registered specs')), f'{cat["registeredSpecs"]:,} registered specs in {len(cat["byKind"])} families, including {cat["byKind"]["inverse"]} Inverse specs. Registration and correctness coverage do not establish financial profitability.')
esc=lambda x:html.escape(str(x))
range_table=''.join(f"<tr><td>{esc(z['tag'])}</td><td>{z['cells']:,}</td><td>{z['normal']:,}</td><td>{z['trailing']:,}</td><td>{z['trailingOnly']:,}</td><td>{z['floor']}</td><td>{z['inverseFloor']}</td></tr>" for z in r)
ci_table=''.join(f"<tr><td>{esc(z['name'])}</td><td>{z.get('files','—')}</td><td>{z.get('pass','—')}</td><td>{z.get('skipped',0)}</td><td>{esc(z.get('status',''))}</td></tr>" for z in ci.get('partitions',[]))
summary=f'''<div class="eyebrow">CTS-A-O · COMBINED VERIFICATION · 21 OCTOBER 2026</div><h1>Inverse. Integrated.<br>Measured and traceable.</h1><p class="lede">20 symbols · Long and Short independently · 1 / 5 / 15 minute foreground benchmark · full registry checks also cover 30 minutes.</p><div class="metrics"><div><span>WARM CYCLE · MEDIAN</span><strong>{b['cycles']['median']:.2f}<small> ms</small></strong><p>p95 {b['cycles']['p95']:.2f} ms · max {b['cycles']['max']:.2f} ms</p></div><div><span>500 MS BUDGET</span><strong>60 / 60</strong><p>Zero overruns or measured failures</p></div><div><span>VALIDATED CONFIGS</span><strong>{q["passedConfigs"]}<small> / {q["candidatesBuilt"]:,}</small></strong><p>{len(rows)} admitted config × direction windows</p></div><div><span>INDEPENDENT TAPE ORACLE</span><strong>172,109</strong><p>Closes match exactly across {b["oracle"]["exactTapes"]} tapes</p></div></div>'''
body=f'''<header>{summary}</header><main><section class="intro"><span class="eyebrow">SCOPE AND EVIDENCE</span><h2>Fast foreground, bounded research.</h2><p>The measured foreground carries forward new finalized candles on the previously validated cohort. Base discovery and set scoring run separately in an owned worker. The next progress invocation starts after the previous one completes; runtime regressions cover overlap, watchdog recovery, cancellation and stale generations.</p><p>This is a repeated retrospective correctness and latency audit on a fixed recorded feed, before venue execution and funding. It is not new out-of-sample alpha evidence. Modeled config/direction histories overlap and must not be summed into a funded portfolio PF. Higher PF or many profitable live orders cannot be inferred from these measurements.</p></section><div class="charts">{''.join(charts)}</div>
<section><span class="eyebrow">EXACT OWN WINDOWS</span><h2>Admitted directions · Last 15 / 15</h2><p>Primary PF below uses the last 15 settled returns belonging to that config and direction at the causal cut (exit ≤ cut). The separate selection window excludes exits exactly at the cut. Both windows and their denominators are retained. Only directions passing all current gates appear here. These histories span the 20-symbol model; symbol-specific owned execution admission remains an additional gate.</p><div class="controls"><label>Find config<input id="query" placeholder="Source, bot or config identity"></label><label>Range<select id="range"><option value="">All ranges</option>{''.join('<option>'+k+'</option>' for k in keys)}</select></label><label>Direction<select id="side"><option value="">Long + Short</option><option value="1">Long</option><option value="-1">Short</option></select></label><button id="reset">Clear</button><button id="csv">Download CSV</button><button id="json">Download evidence JSON</button></div><p id="count" aria-live="polite"></p><div class="table-wrap lastn"><table><thead><tr><th>Config identity</th><th>Range / type</th><th>Side</th><th>Own N / requested</th><th>Own Last-N PF</th><th>Window N / PF</th><th>Own settled window, UTC</th></tr></thead><tbody id="rows"></tbody></table></div></section>
<section><span class="eyebrow">RANGES AND PROTECTION</span><h2>Factory configuration catalog</h2><p>Micro (mc), Minimal (mn), Minimal Plus (mp), Short (sh), General (gn), Long (lg) and Wide are distinct ranges. Independent normal, TP with trailing, and trailing-only cells are shown below. Exit, DCA, DCA-active, Axis and Block have dedicated builders and tests; these static protect counts are not their Cartesian total. Distances and holds use the actual lane conversion. No range or threshold was relaxed for this report.</p><div class="table-wrap"><table><thead><tr><th>Range</th><th>Cells</th><th>TP + SL</th><th>TP + trailing</th><th>Trailing only</th><th>PF floor</th><th>Inverse floor</th></tr></thead><tbody>{range_table}</tbody></table></div><p>Factory lanes: {esc(defaults['tfs'])}; focus identities: {defaults['focusCount']}. Own validation N: {defaults['wf']['validLastN']}; engine window: {defaults['wf']['longH']} h with {defaults['wf']['preH']} h prehistory. Signal window: {defaults['wf']['signalLongH']} h / {defaults['wf']['signalValidLastN']} closes. Actual deployed settings and the frozen benchmark profile are separate from these defaults.</p></section>
<section><span class="eyebrow">COMPLETE INVENTORY, EXPLICIT SCOPE</span><h2>Verification ledger</h2><p>Status: <strong>{esc(ci['status'])}</strong>. Ordinary core files are partitioned without omissions or duplicates. Optional slow runtime cases are covered in their dedicated job. Counts below are disjoint within that ordinary inventory; extra stress, oracle and universal checks are separate evidence.</p><div class="table-wrap"><table><thead><tr><th>Partition / check</th><th>Files</th><th>Passed</th><th>Skipped</th><th>Outcome</th></tr></thead><tbody>{ci_table}</tbody></table></div><p>The current sealed universal audit checks all {cat["registeredSpecs"]:,} sources, {ci.get("identityCells",0):,} synthetic identity cells, 20 native-price symbols with 96 h history, six hourly causal cuts and three unfinished-bar cuts. Zero violations. Static default cells remain unchanged; the identity catalog supplements Wide with 12 cells and Minimal Plus with 6 per lane. This checks identities, calculations, causal state and gates, rather than every possible market/parameter combination or future profitability.</p><p>Unknown or nonfinite returns stay unknown; they cannot become zero, inherit a winning sibling, or fall back to old paper wins. Nominal paper history and captured forward book retain separate ownership and cash provenance. Raw/unfiltered PF below 1 is normal for every type; configured positive thresholds apply from Base and later gates.</p><p>CI: <a href="https://github.com/mxssnx-creator/CTS-A-O/actions/runs/39535290120">ordinary core + stress</a> · <a href="https://github.com/mxssnx-creator/CTS-A-O/actions/runs/39535290111">slow + universal</a> · <a href="https://github.com/mxssnx-creator/CTS-A-O/actions/runs/39535290093">scripts, app, types, lint and build</a>. Failed first attempts remain archived; the Settings-save UI timeout is recorded alongside its bounded rerun and local full run.</p></section>
<section><span class="eyebrow">REPRODUCIBILITY</span><h2>Same bytes, visible limits.</h2><p>Symbols: {esc(', '.join(b['symbols']))}.</p><p>Cold candidate build {b['candidateBuildMs']/1000:.2f} s; runtime bootstrap {b['bootstrapMs']/1000:.2f} s; independent oracle {b['oracle']['ms']/1000:.2f} s. Peak process RSS {b['peakRssMiB']:.2f} MiB includes cold discovery and the full-history oracle. These cold phases do not meet the 500 ms foreground budget. Benchmark research interval {b['researchIntervalMs']/60000:.0f} min (production default {b['researchDefaultMs']/60000:.0f} min); no background research overlaps the measured foreground. Host changed during recovery, so these numbers are not an A/B speedup claim.</p><p>The oracle compares every numeric tape column, prefix, open and pending position. End state: {b['end']['positions']} modeled open positions and {b['end']['closed']} closed virtual trades; zero measured foreground research rebuilds. Recorded-feed execution is offline; no account, venue order or deployment was operated by this audit.</p><dl><dt>Economic source seal</dt><dd><code>{manifest['sourceSha256']}</code></dd><dt>Core benchmark source seal</dt><dd><code>{b['sourceSha256']}</code></dd><dt>Recorded compressed feed SHA-256</dt><dd><code>{b['feedSha256']}</code></dd><dt>Frozen protocol SHA-256</dt><dd><code>{b['protocolSha256']}</code></dd></dl><p>The broader seal includes session/simulation code; the core-only seal additionally includes test-support.ts. Every shared production file hash is checked by this generator. The feed is restored from committed chunks and verified before use. All report data and SVG charts are embedded; filters and downloads work offline.</p></section></main><footer>CTS-A-O · source-sealed integration evidence · no external assets</footer>'''
css='''*{box-sizing:border-box}body{margin:0;background:#f1f4f8;color:#182b45;font:15px/1.65 system-ui,sans-serif}header{background:#122438;color:#fff;padding:52px max(24px,calc((100vw - 1380px)/2)) 34px}.eyebrow{font-size:11px;letter-spacing:2px;font-weight:750;color:#659aaa}h1{font-size:clamp(38px,5vw,70px);line-height:1.08;letter-spacing:-2px;margin:18px 0}h2{font-size:28px;line-height:1.2;letter-spacing:-.7px}h3{font-size:17px;margin:0 0 14px}.lede{color:#b9cada;max-width:770px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:35px}.metrics>div{border:1px solid #345064;border-radius:12px;padding:20px;background:#193147}.metrics span{font-size:10px;letter-spacing:1.4px;color:#a7c4d0}.metrics strong{display:block;font-size:36px;letter-spacing:-1px;margin:8px 0}.metrics small{font-size:16px;font-weight:400;letter-spacing:0}.metrics p{font-size:12px;color:#b9cada;margin:0}main{max-width:1430px;margin:auto;padding:24px}.intro{max-width:100%}section{padding:30px;background:white;border:1px solid #dbe3ec;border-radius:14px;margin:22px 0}section p{max-width:1150px;color:#42536a}.charts{display:grid;grid-template-columns:1fr 1fr;gap:20px}.chart{background:white;border:1px solid #dbe3ec;border-radius:14px;padding:24px;min-width:0}.chart svg{width:100%;height:auto;display:block}.chart p{font-size:12px;color:#52647b;line-height:1.6;margin-bottom:0}.controls{display:flex;flex-wrap:wrap;align-items:end;gap:10px}.controls label{font-size:12px;color:#42536a}.controls input,.controls select{display:block;margin-top:5px;max-width:100%;padding:10px;border:1px solid #c4d1df;border-radius:7px;background:#fff;color:#182b45}.controls input{width:250px}button{border:0;border-radius:7px;background:#126e7d;color:white;padding:11px 13px;cursor:pointer}.table-wrap{overflow:auto;border:1px solid #dbe3ec;border-radius:8px;max-width:100%}.lastn{max-height:580px}table{border-collapse:collapse;width:100%;font-size:12px}th,td{text-align:left;padding:12px 14px;border-bottom:1px solid #e5eaf0;vertical-align:top}th{position:sticky;top:0;background:#edf3f7;white-space:nowrap;z-index:1}td code{display:block;width:320px;overflow-wrap:anywhere;font-size:11px}.lastn table{min-width:1040px}tbody tr:nth-child(even){background:#f8fafc}code{font-size:12px;overflow-wrap:anywhere}dt{font-size:12px;font-weight:700;margin-top:16px}dd{margin:4px 0;word-break:break-all}footer{text-align:center;color:#607189;padding:30px;font-size:12px}a{color:#126e7d}#count{font-weight:650;font-size:13px}@media(max-width:800px){.metrics{grid-template-columns:1fr 1fr}.charts{grid-template-columns:1fr}header{padding:30px 20px}.metrics>div{padding:15px}.metrics strong{font-size:27px}main{padding:12px}section{padding:20px}.chart{padding:18px}.controls{align-items:stretch}.controls label{flex:1;min-width:130px}.controls input,.controls select{width:100%}h2{font-size:24px}body{font-size:14px}}'''
evidence={'benchmark':b,'qualification':q,'sourceCatalog':cat,'ranges':ranges,'factory':defaults,'sourceManifest':manifest,'ci':ci}
js='''const evidence=JSON.parse(document.getElementById('evidence').textContent);const all=evidence.qualification.configs.flatMap(c=>c.directions.filter(d=>d.ok).map(d=>({id:c.id,kind:c.kind,range:c.range,...d})));const $=s=>document.querySelector(s);const date=t=>new Date(t).toISOString().replace('.000Z','Z');const fmt=x=>Number(x).toFixed(3);function render(){const query=$('#query').value.toLowerCase(),range=$('#range').value,side=$('#side').value;const rows=all.filter(r=>(!query||r.id.toLowerCase().includes(query))&&(!range||r.range===range)&&(!side||r.side===Number(side)));$('#count').textContent=`${rows.length} / ${all.length} admitted direction windows · ${evidence.qualification.passedConfigs} / ${evidence.qualification.candidatesBuilt} configs · own Last 15 / 15`;$('#rows').replaceChildren(...rows.map(r=>{const tr=document.createElement('tr');const values=[r.id,r.range+' / '+r.kind,r.side===1?'Long':'Short',r.lastN+' / '+r.lastNRequested,r.noLoss?'No loss · score '+r.lastNPf:fmt(r.lastNPf),r.windowN+' / '+fmt(r.windowPf),date(r.fromT)+' → '+date(r.toT)];values.forEach((v,i)=>{const td=document.createElement('td');const node=document.createElement(i===0?'code':'span');node.textContent=v;td.append(node);tr.append(td)});return tr}));}for(const s of ['#query','#range','#side'])$(s).addEventListener('input',render);$('#reset').onclick=()=>{for(const s of ['#query','#range','#side'])$(s).value='';render()};function download(name,type,content){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}$('#json').onclick=()=>download('combined-verification.json','application/json',JSON.stringify(evidence,null,2));$('#csv').onclick=()=>{const keys=['id','kind','range','side','lastN','lastNRequested','lastNPf','noLoss','lastNGp','lastNGl','windowN','windowPf','fromT','toT'];const quote=v=>'"'+String(v).replaceAll('"','""')+'"';download('validated-last15.csv','text/csv',[keys.join(','),...all.map(r=>keys.map(k=>quote(r[k])).join(','))].join('\\n')+'\\n')};render();'''
(D/'index.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>CTS-A-O · Combined verification</title><style>'+css+'</style>'+body+'<script id="evidence" type="application/json">'+json.dumps(evidence,separators=(',',':')).replace('<','\\u003c')+'</script><script>'+js+'</script></html>')
print(json.dumps({'htmlBytes':(D/'index.html').stat().st_size,'charts':len(charts),'admittedDirections':len(rows),'noLossWindows':no_loss,'lossBearingPfMin':min(pfs),'lossBearingPfMax':max(pfs)}))
